22	class ResumeDriver
23	{
24	public:
25	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
26	  // dmcontrol/dmstatus are run-control registers specific to this driver.
27	  static constexpr uint8_t kData0      = kDmiData0;
28	  static constexpr uint8_t kData1      = kDmiData1;
29	  static constexpr uint8_t kDmcontrol  = 0x10;
30	  static constexpr uint8_t kDmstatus   = 0x11;
31	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
32	  static constexpr uint8_t kCommand    = kDmiCommand;
33	
34	  static constexpr uint16_t kCsrDpc = 0x7B1;
35	
36	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
37	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
38	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
39	
40	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
41	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
42	
43	  static constexpr uint32_t kAbstractcsBusy       = hybrid::kAbstractcsBusy;
44	  static constexpr uint32_t kAbstractcsCmderrMask = hybrid::kAbstractcsCmderrMask;
45	
46	  static constexpr unsigned kPollIterations = kDmiPollIterations;
47	
48	  explicit ResumeDriver(DmiBus& bus) : bus_{bus} {}
49	
50	  void resume(const hybrid_state_v1& state)
51	  {
52	    if (state.magic != HYBRID_STATE_MAGIC)
53	      throw std::runtime_error("ResumeDriver::resume: bad magic");
54	    if (state.version != HYBRID_STATE_VERSION)
55	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
56	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
57	    if (state.priv == 2 || state.priv > 3)
58	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
59	
60	    // dmactive must transition 0->1 in its own write before any other
61	    // DMCONTROL bit is honored (RISC-V Debug Spec).
62	    bus_.write(kDmcontrol, kDmcontrolDmactive);
63	    request_halt();
64	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
65	
66	    // Minimal slice: only GPR x1 and DPC. One abstract register write each
67	    // (DATA0/DATA1 + Access-Register COMMAND), abstract-only by design. The
68	    // rest of the register file (x2..x31, FPRs, CSRs, PMP, V) lands in the
69	    // completion commits.
70	    write_64bit_register(regno_gpr(1), state.gpr[1]);
71	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
72	
73	    request_resume();
74	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
75	                   "ResumeDriver resume");
76	  }
77	
78	private:
79	  void request_halt()
80	  {
81	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
82	  }
83	
84	  void request_resume()
85	  {
86	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
87	  }
88	
89	  void write_64bit_register(uint16_t regno, uint64_t value)
90	  {
91	    write_register_abstract(bus_, regno, value);
92	  }
93	
94	  DmiBus& bus_;
95	};
