97	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
98	// via an Abstract Command. Halts-and-reads contract: caller must have the
99	// hart in the halted state. Shared with StateDrain (drain at exit). If
100	// abstractcs.cmderr goes sticky after the command, the helper clears it and
101	// reports nullopt rather than blocking the caller -- a missing CSR mirrors as
102	// absent instead of corrupting the adjacent field.
103	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
104	                                     const char* poll_label
105	                                       = "read_register_64")
106	  -> std::optional<uint64_t>
107	{
108	  using RD = ResumeDriver;
109	  bus.write(RD::kCommand,
110	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
111	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
112	  const auto status = bus.read(RD::kAbstractcs);
113	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
114	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
115	    return std::nullopt;
116	  }
117	  const uint64_t lo = bus.read(RD::kData0);
118	  const uint64_t hi = bus.read(RD::kData1);
119	  return lo | (hi << 32);
120	}
121	
122	inline auto read_register_64(DmiBus& bus, uint16_t regno,
123	                             const char* poll_label = "read_register_64")
124	  -> uint64_t
125	{
126	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
127	}
