1	// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
2	// ops against the RISC-V Debug Module. The orchestration is testable in
3	// isolation by injecting a recording bus.
4	//
5	// Minimal slice: the driver restores only GPR x1 and DPC. These cases pin the
6	// halt/resume handshake, the x1 program, the DPC write and the header guard.
7	
8	#include "hybrid/abstract_command.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
