12	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
13	#include <doctest.h>
14	
15	#include <cstdint>
16	#include <optional>
17	#include <vector>
18	
19	namespace {
20	
21	// DMI register addresses from RISC-V Debug Spec 1.0.
22	constexpr uint8_t kDmcontrol  = 0x10;
23	constexpr uint8_t kDmstatus   = 0x11;
24	constexpr uint8_t kCommand    = 0x17;
25	constexpr uint8_t kData0      = 0x04;
26	constexpr uint8_t kData1      = 0x05;
27	
28	// CSR numbers from Debug Spec.
29	constexpr uint16_t kCsrDpc = 0x7B1;
30	
31	struct DmiOp
32	{
33	  enum class Kind
34	  {
35	    Write,
36	    Read,
37	  };
38	  Kind kind;
39	  uint8_t reg;
40	  uint32_t value;  // for writes only
41	};
42	
43	struct RecordingBus final : hybrid::DmiBus
44	{
45	  std::vector<DmiOp> ops;
46	
47	  // bit 9: allhalted, bit 17: allresumeack. Answering both lets the poll
48	  // loops finish on their first read. abstractcs reads return 0 (busy clear,
49	  // no cmderr), so each abstract write completes immediately.
50	  uint32_t dmstatus_value = 0;
51	
52	  void write(uint8_t reg, uint32_t value) override
53	  {
54	    ops.push_back({DmiOp::Kind::Write, reg, value});
55	  }
56	
57	  auto read(uint8_t reg) -> uint32_t override
58	  {
59	    ops.push_back({DmiOp::Kind::Read, reg, 0});
60	    if (reg == kDmstatus) return dmstatus_value;
61	    return 0;
62	  }
63	};
64	
65	auto rv64_state(uint64_t pc, uint64_t x1) -> hybrid_state_v1
66	{
67	  hybrid_state_v1 s{};
68	  s.magic = HYBRID_STATE_MAGIC;
69	  s.version = HYBRID_STATE_VERSION;
70	  s.flags = HYBRID_FLAG_RV64;
71	  s.pc = pc;
72	  s.priv = 3;
73	  s.gpr[1] = x1;
74	  return s;
75	}
76	
77	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
78	  -> std::vector<uint32_t>
79	{
80	  std::vector<uint32_t> values;
81	  for (const auto& op : ops)
82	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
83	      values.push_back(op.value);
84	  return values;
85	}
86	
87	}  // namespace
