89	TEST_CASE("resume halts the hart before any abstract command")
90	{
91	  RecordingBus bus;
92	  bus.dmstatus_value = (1u << 9) | (1u << 17);
93	
94	  hybrid::ResumeDriver driver(bus);
95	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x1=*/0xdeadbeef));
96	
97	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
98	  // accepted; the second write must add haltreq while keeping dmactive set.
99	  REQUIRE(bus.ops.size() >= 2);
100	
101	  const auto& prime = bus.ops[0];
102	  CHECK(prime.kind == DmiOp::Kind::Write);
103	  CHECK(prime.reg == kDmcontrol);
104	  CHECK((prime.value & 1u) == 1u);                  // dmactive
105	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
106	
107	  const auto& halt = bus.ops[1];
108	  CHECK(halt.kind == DmiOp::Kind::Write);
109	  CHECK(halt.reg == kDmcontrol);
110	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
111	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
112	}
