130	        && ((op.value >> 16) & 1u)) {
131	      x1_cmd_idx = i;
132	      break;
133	    }
134	  }
135	  REQUIRE(x1_cmd_idx.has_value());
136	
137	  const auto expect =
138	    hybrid::access_register_command(hybrid::regno_gpr(1),
139	                                    hybrid::AarSize::Bits64, /*write=*/true);
140	  CHECK(bus.ops[*x1_cmd_idx].value == expect);
141	
142	  REQUIRE(*x1_cmd_idx >= 2);
143	  const auto& d0 = bus.ops[*x1_cmd_idx - 2];
144	  const auto& d1 = bus.ops[*x1_cmd_idx - 1];
145	  CHECK(d0.reg == kData0);
146	  CHECK(d0.value == uint32_t(x1 & 0xffffffffu));
147	  CHECK(d1.reg == kData1);
148	  CHECK(d1.value == uint32_t(x1 >> 32));
149	
150	  // x0 is never programmed.
151	  for (const auto& op : bus.ops)
152	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
