// Access-Register COMMAND), abstract-only by design. x0 is hardwired zero
// and is skipped. FPRs, M-mode CSRs, PMP and V land in later commits;
// M-mode CSRs/PMP are pass-through-merged at drain time, never programmed
// through a DM abstract command here.
for (uint16_t i = 1; i < 32; ++i)
  write_64bit_register(regno_gpr(i), state.gpr[i]);
write_64bit_register(regno_csr(kCsrDpc), state.pc);

// GPR transport complete: the driver restores GPRs x1..x31 and DPC. These
// cases pin the halt/resume handshake, the x1..x31 program (one COMMAND per
// register, x0 skipped), the DPC write, that M-mode CSRs/PMP are NOT programmed
// via DM abstract at this stage, and the header guard.

