TEST_CASE("resume programs x1 via DATA0/DATA1 + COMMAND, skipping x0")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  constexpr uint64_t x1 = 0x0123456789ABCDEFULL;
  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, x1));

  // Find the COMMAND write that programs x1 (regno = 0x1000 + 1); the value
  // rides the DATA0/DATA1 written immediately before it.
  std::optional<std::size_t> x1_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xffffu) == hybrid::regno_gpr(1)
        && ((op.value >> 16) & 1u)) {
      x1_cmd_idx = i;
      break;
    }
  }
  REQUIRE(x1_cmd_idx.has_value());

  const auto expect =
    hybrid::access_register_command(hybrid::regno_gpr(1),
                                    hybrid::AarSize::Bits64, /*write=*/true);
  CHECK(bus.ops[*x1_cmd_idx].value == expect);

  REQUIRE(*x1_cmd_idx >= 2);
  const auto& d0 = bus.ops[*x1_cmd_idx - 2];
  const auto& d1 = bus.ops[*x1_cmd_idx - 1];
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(x1 & 0xffffffffu));
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t(x1 >> 32));

  // x0 is never programmed.
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
      CHECK((op.value & 0xffffu) != hybrid::regno_gpr(0));
}

